"""Seed problems. Expected outputs for hidden cases are generated by the trusted reference
functions below at seed time (deterministic RNG) -- this code is ours, not user-submitted."""

import heapq
import random
from bisect import bisect_left


def _ints(line: str) -> list[int]:
    return [int(x) for x in line.split()]


def ref_a_plus_b(inp):
    a, b = _ints(inp)
    return str(a + b)


def ref_two_sum(inp):
    lines = inp.strip().split("\n")
    arr, target = _ints(lines[1]), int(lines[2])
    for j in range(len(arr)):
        for i in range(j):
            if arr[i] + arr[j] == target:
                return f"{i + 1} {j + 1}"
    return "-1"


def ref_parens(inp):
    stack, pairs = [], {")": "(", "]": "[", "}": "{"}
    for ch in inp.strip():
        if ch in "([{":
            stack.append(ch)
        elif not stack or stack.pop() != pairs[ch]:
            return "NO"
    return "NO" if stack else "YES"


def ref_reverse_words(inp):
    return " ".join(reversed(inp.split()))


def ref_max_subarray(inp):
    arr = _ints(inp.strip().split("\n")[1])
    best = cur = arr[0]
    for x in arr[1:]:
        cur = max(x, cur + x)
        best = max(best, cur)
    return str(best)


def ref_lower_bound(inp):
    lines = inp.strip().split("\n")
    arr, queries = _ints(lines[1]), _ints(lines[3])
    return "\n".join(
        str(bisect_left(arr, q) + 1) if bisect_left(arr, q) < len(arr) else "-1" for q in queries
    )


def ref_coin_change(inp):
    lines = inp.strip().split("\n")
    coins, amount = _ints(lines[1]), int(lines[2])
    inf = 10**9
    dp = [0] + [inf] * amount
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a and dp[a - c] + 1 < dp[a]:
                dp[a] = dp[a - c] + 1
    return str(dp[amount] if dp[amount] < inf else -1)


def ref_lis(inp):
    tails: list[int] = []
    for x in _ints(inp.strip().split("\n")[1]):
        i = bisect_left(tails, x)
        tails[i : i + 1] = [x]
    return str(len(tails))


def ref_islands(inp):
    lines = inp.strip().split("\n")
    r, c = _ints(lines[0])
    grid = [list(row) for row in lines[1 : 1 + r]]
    seen, count = set(), 0
    for i in range(r):
        for j in range(c):
            if grid[i][j] == "1" and (i, j) not in seen:
                count += 1
                stack = [(i, j)]
                seen.add((i, j))
                while stack:
                    x, y = stack.pop()
                    for nx, ny in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
                        if (
                            0 <= nx < r
                            and 0 <= ny < c
                            and grid[nx][ny] == "1"
                            and (nx, ny) not in seen
                        ):
                            seen.add((nx, ny))
                            stack.append((nx, ny))
    return str(count)


def ref_dijkstra(inp):
    lines = inp.strip().split("\n")
    n, m = _ints(lines[0])
    adj = [[] for _ in range(n + 1)]
    for line in lines[1 : 1 + m]:
        u, v, w = _ints(line)
        adj[u].append((v, w))
        adj[v].append((u, w))
    dist = [None] * (n + 1)
    heap = [(0, 1)]
    while heap:
        d, u = heapq.heappop(heap)
        if dist[u] is not None:
            continue
        dist[u] = d
        for v, w in adj[u]:
            if dist[v] is None:
                heapq.heappush(heap, (d + w, v))
    return str(dist[n] if dist[n] is not None else -1)


def ref_inversions(inp):
    arr = _ints(inp.strip().split("\n")[1])

    def sort(a):
        if len(a) <= 1:
            return a, 0
        mid = len(a) // 2
        left, x = sort(a[:mid])
        right, y = sort(a[mid:])
        merged, i, j, inv = [], 0, 0, x + y
        while i < len(left) and j < len(right):
            if left[i] <= right[j]:
                merged.append(left[i])
                i += 1
            else:
                merged.append(right[j])
                j += 1
                inv += len(left) - i
        return merged + left[i:] + right[j:], inv

    return str(sort(arr)[1])


def _arr_case(rng, n, lo, hi, extra=""):
    arr = [rng.randint(lo, hi) for _ in range(n)]
    return f"{n}\n{' '.join(map(str, arr))}{extra}"


def gen_a_plus_b(rng):
    return [f"{rng.randint(-(10**9), 10**9)} {rng.randint(-(10**9), 10**9)}" for _ in range(5)] + [
        "0 0"
    ]


def gen_two_sum(rng):
    out = []
    for n in (2, 5, 50, 500, 2000):
        arr = [rng.randint(-(10**6), 10**6) for _ in range(n)]
        i, j = sorted(rng.sample(range(n), 2))
        out.append(f"{n}\n{' '.join(map(str, arr))}\n{arr[i] + arr[j]}")
    out.append("3\n1 2 3\n100")
    return out


def gen_parens(rng):
    out = ["()", "([)]", "{[]}", "(((", ")", "([]){}"]
    for _ in range(5):
        s = "".join(rng.choice("()[]{}") for _ in range(rng.randint(2, 40)))
        out.append(s)
    return out


def gen_words(rng):
    vocab = ["alpha", "beta", "gamma", "delta", "x", "yz", "codearena", "judge"]
    return [" ".join(rng.choice(vocab) for _ in range(rng.randint(1, 30))) for _ in range(6)]


def gen_maxsub(rng):
    return [_arr_case(rng, n, -50, 50) for n in (1, 2, 8, 100, 1000)] + ["3\n-3 -1 -2"]


def gen_lower(rng):
    out = []
    for n in (1, 6, 50, 500):
        arr = sorted(rng.randint(1, 1000) for _ in range(n))
        qs = [rng.randint(0, 1100) for _ in range(5)]
        out.append(f"{n}\n{' '.join(map(str, arr))}\n5\n{' '.join(map(str, qs))}")
    return out


def gen_coin(rng):
    out = ["3\n1 2 5\n11", "1\n2\n3", "2\n3 7\n1"]
    for _ in range(4):
        coins = sorted(rng.sample(range(1, 30), rng.randint(2, 5)))
        out.append(f"{len(coins)}\n{' '.join(map(str, coins))}\n{rng.randint(1, 1000)}")
    return out


def gen_lis(rng):
    return [_arr_case(rng, n, 1, 10**6) for n in (1, 5, 30, 500, 5000)] + ["5\n5 4 3 2 1"]


def gen_islands(rng):
    out = ["3 3\n111\n010\n111", "2 2\n10\n01"]
    for r, c in ((5, 5), (10, 12), (30, 30)):
        grid = ["".join(rng.choice("0011") for _ in range(c)) for _ in range(r)]
        out.append(f"{r} {c}\n" + "\n".join(grid))
    return out


def gen_dijkstra(rng):
    out = ["3 2\n1 2 5\n2 3 7", "3 1\n1 2 4"]
    for n, m in ((6, 10), (50, 120), (500, 2000)):
        edges = {
            (min(a, b), max(a, b))
            for a, b in ((rng.randint(1, n), rng.randint(1, n)) for _ in range(m))
            if a != b
        }
        lines = [f"{u} {v} {rng.randint(1, 100)}" for u, v in sorted(edges)]
        out.append(f"{n} {len(lines)}\n" + "\n".join(lines))
    return out


def gen_inversions(rng):
    return [_arr_case(rng, n, 1, 10**5) for n in (1, 6, 40, 1000, 5000)] + ["4\n4 3 2 1"]


