def build_cases(spec: dict) -> list[dict]:
    rng = random.Random(spec["slug"])  # deterministic
    ref = spec["ref"]
    cases = [{"input": s, "expected_output": ref(s), "is_sample": True} for s in spec["samples"]]
    cases += [{"input": s, "expected_output": ref(s), "is_sample": False} for s in spec["gen"](rng)]
    return cases
